-- The row feed (0106) for the project's own row (its settings), the speakers and the known listeners
-- (src/services/project-rows.ts), and a scene's row now also counts the lines AI decided (status_by).
-- A speaker's row changes with the lines that name it and with the characters it may be; a listener's with the lines
-- addressed to it. A migration that rebuilds one of these tables must make its triggers again.
CREATE TRIGGER `feed_project_update` AFTER UPDATE ON `projects` BEGIN SELECT row_changed('project', NEW.`id`, 'upsert', NEW.`id`); END;--> statement-breakpoint
DROP TRIGGER IF EXISTS `feed_groups_unit_update`;--> statement-breakpoint
CREATE TRIGGER `feed_groups_unit_update` AFTER UPDATE OF `group_id`, `status_id`, `status_by`, `source`, `translate`, `kind`, `speaker`, `listener`, `listener_origin`, `listener_confidence` ON `units` BEGIN SELECT row_changed('groups', NEW.`group_id`, 'upsert', NEW.`project_id`); SELECT row_changed('groups', OLD.`group_id`, 'upsert', OLD.`project_id`) WHERE OLD.`group_id` != NEW.`group_id`; END;--> statement-breakpoint
CREATE TRIGGER `feed_speakers_unit_insert` AFTER INSERT ON `units` BEGIN SELECT row_changed('speakers', coalesce(NEW.`speaker`, ''), 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_speakers_unit_delete` AFTER DELETE ON `units` BEGIN SELECT row_changed('speakers', coalesce(OLD.`speaker`, ''), 'upsert', OLD.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_speakers_unit_update` AFTER UPDATE OF `speaker` ON `units` BEGIN SELECT row_changed('speakers', coalesce(NEW.`speaker`, ''), 'upsert', NEW.`project_id`); SELECT row_changed('speakers', coalesce(OLD.`speaker`, ''), 'upsert', OLD.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_speakers_character_insert` AFTER INSERT ON `characters` BEGIN SELECT row_changed('speakers', coalesce(`speaker`, ''), 'upsert', NEW.`project_id`) FROM (SELECT DISTINCT `speaker` FROM `units` WHERE `project_id` = NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_speakers_character_update` AFTER UPDATE OF `name`, `aliases` ON `characters` BEGIN SELECT row_changed('speakers', coalesce(`speaker`, ''), 'upsert', NEW.`project_id`) FROM (SELECT DISTINCT `speaker` FROM `units` WHERE `project_id` = NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_speakers_character_delete` AFTER DELETE ON `characters` BEGIN SELECT row_changed('speakers', coalesce(`speaker`, ''), 'upsert', OLD.`project_id`) FROM (SELECT DISTINCT `speaker` FROM `units` WHERE `project_id` = OLD.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_listeners_unit_insert` AFTER INSERT ON `units` WHEN NEW.`listener` IS NOT NULL BEGIN SELECT row_changed('listeners', NEW.`listener`, 'upsert', NEW.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_listeners_unit_delete` AFTER DELETE ON `units` WHEN OLD.`listener` IS NOT NULL BEGIN SELECT row_changed('listeners', OLD.`listener`, 'upsert', OLD.`project_id`); END;--> statement-breakpoint
CREATE TRIGGER `feed_listeners_unit_update` AFTER UPDATE OF `listener`, `listener_origin`, `listener_confidence` ON `units` BEGIN SELECT row_changed('listeners', NEW.`listener`, 'upsert', NEW.`project_id`) WHERE NEW.`listener` IS NOT NULL; SELECT row_changed('listeners', OLD.`listener`, 'upsert', OLD.`project_id`) WHERE OLD.`listener` IS NOT NULL; END;
